import java.io.*;
import java.util.*;

public class VanyaAndScaleVariant2 {
    static long[] a;
    static boolean found;
    static int total;
    static long sumLeft, sumRight;

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tokens = new StringTokenizer(reader.readLine());
        long weight = Long.parseLong(tokens.nextToken());
        long target = Long.parseLong(tokens.nextToken());
        long maxLimit = (long) 1e11;
        a = new long[40];
        int indexCount = 1;
        long powerVal = 1;
        a[0] = 1;
        if (weight <= 3) {
            System.out.println("YES");
            return;
        }
        for (int i = 1; i < 16; i++) {
            a[indexCount] = powerVal * weight;
            powerVal *= weight;
            if (powerVal > maxLimit) break;
            indexCount++;
        }
        sumLeft = 0;
        sumRight = target;
        total = indexCount;
        found = false;
        search(0);
        System.out.println(found ? "YES" : "NO");
    }

    static void search(int position) {
        if (position == total) {
            if (sumLeft == sumRight) {
                found = true;
            }
            return;
        }
        if (found) return;
        for (int option = 0; option < 3; option++) {
            if (found) return;
            if (option == 1) {
                sumLeft += a[position];
                search(position + 1);
                sumLeft -= a[position];
            } else if (option == 2) {
                sumRight += a[position];
                search(position + 1);
                sumRight -= a[position];
            } else {
                search(position + 1);
            }
        }
    }
}
